#!/usr/bin/env node
/**
 * Builds the zero-dependency browser ES module (`docs/msfpdf-browser.js`) directly from
 * `packages/ts/src/*.ts` using TypeScript's compiler API, and syncs AI discovery artifacts
 * (`llms.txt`, `llms-full.txt`, `schemas/document-spec.schema.json`, `.nojekyll`) into `docs/`.
 */

import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import ts from 'typescript';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

const MODULE_ORDER = [
  'types.ts',
  'glyphsData.ts',
  'shaping.ts',
  'encoding.ts',
  'qr.ts',
  'renderer.ts',
];

function stripRelativeImportsAndExports(jsCode) {
  return jsCode
    // Remove multi-line or single-line relative imports (`import { ... } from './foo.ts';`)
    .replace(/^\s*import\s+[\s\S]*?\s+from\s+['"]\.\/[^'"]+['"];?\s*$/gm, '')
    // Strip `export ` prefix from declarations so modules share one clean top-level scope
    .replace(/^export\s+(async\s+function|function|class|const|let|var)\b/gm, '$1')
    // Remove standalone `export { ... };` statements
    .replace(/^\s*export\s*\{[\s\S]*?\};?\s*$/gm, '');
}

export function buildShowcaseBundle() {
  const chunks = [
    '// @generated by scripts/build-showcase-bundle.mjs — DO NOT EDIT MANUALLY.',
    '// taste-skill-ignore',
    '// Zero-dependency browser ES2022 bundle of msfPDF (Latin + Cyrillic + Connected Arabic RTL).',
    '',
  ];

  for (const filename of MODULE_ORDER) {
    const absPath = join(ROOT, 'packages', 'ts', 'src', filename);
    const source = readFileSync(absPath, 'utf8');
    const transpiled = ts.transpileModule(source, {
      fileName: filename,
      compilerOptions: {
        target: ts.ScriptTarget.ES2022,
        module: ts.ModuleKind.ES2022,
        removeComments: false,
      },
    });
    chunks.push(`// --- ${filename} ---`);
    chunks.push(stripRelativeImportsAndExports(transpiled.outputText).trim());
    chunks.push('');
  }

  chunks.push(
    'export {',
    '  DEFAULT_SECURITY_LIMITS,',
    '  MsfPdfError,',
    '  encodeQr,',
    '  estimateFontWidthPt,',
    '  formatMoneyMinor,',
    '  hasArabicOrRtl,',
    '  isRtlDominant,',
    '  pdfEscapeWinAnsi,',
    '  renderDocument,',
    '  renderDocumentJson,',
    '  shapeAndReorderLine,',
    '  shapeArabicLogical,',
    '  truncateToWidthPt,',
    '  wrapTextToWidthPt,',
    '};',
    ''
  );

  const docsDir = join(ROOT, 'docs');
  const docsSchemasDir = join(docsDir, 'schemas');
  mkdirSync(docsSchemasDir, { recursive: true });

  const outPath = join(docsDir, 'msfpdf-browser.min.js');
  writeFileSync(outPath, chunks.join('\n'), 'utf8');

  // Sync AI discovery & structured schema files into docs/ for GitHub Pages root serving
  copyFileSync(join(ROOT, 'llms.txt'), join(docsDir, 'llms.txt'));
  copyFileSync(join(ROOT, 'llms-full.txt'), join(docsDir, 'llms-full.txt'));
  copyFileSync(
    join(ROOT, 'schemas', 'document-spec.schema.json'),
    join(docsSchemasDir, 'document-spec.schema.json')
  );
  writeFileSync(join(docsDir, '.nojekyll'), '', 'utf8');

  return outPath;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const outPath = buildShowcaseBundle();
  console.log(`Built browser bundle and synced AI discovery assets -> ${outPath}`);
}
